mapper.select:
SELECT COUNT(*) > 0
FROM course_reservation
WHERE member_account = #{memberAccount}
AND coach_account = #{coachAccount}
AND reservation_date = #{reservationDate}
AND period = #{period}

mapper.delete:
DELETE FROM course_reservation
WHERE member_account = #{memberAccount}
AND coach_account = #{coachAccount}
AND reservation_date = #{reservationDate}
AND period = #{period}

mapper.select:
SELECT r.*, m.member_name, c.coach_name
FROM course_reservation r
LEFT JOIN member m ON r.member_account = m.member_account
LEFT JOIN coach c ON r.coach_account = c.coach_account
WHERE r.coach_account = #{coachAccount}
AND r.reservation_date = #{reservationDate}

SELECT COUNT(*)
FROM course_reservation
WHERE member_account = #{memberAccount}
AND coach_account = #{coachAccount}
AND reservation_date = #{reservationDate}
AND period = #{period}
